SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS hrm_payroll_offset (
 id bigint NOT NULL AUTO_INCREMENT PRIMARY KEY,batch_id bigint,entity_id bigint,employee_id bigint,source_id bigint,submitted_by bigint,reviewed_by bigint,consumed_payment_id bigint,net_amount decimal(20,2),source_type varchar(32),source_digest varchar(64),status varchar(32),evidence varchar(1000),review_reason varchar(1000),request_key varchar(100),request_snapshot LONGTEXT,reviewed_time datetime,
 creator varchar(64) DEFAULT '',create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,updater varchar(64) DEFAULT '',update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted bit NOT NULL DEFAULT FALSE,tenant_id bigint NOT NULL DEFAULT 0,
 UNIQUE KEY uk_payroll_offset_request(tenant_id,request_key),active_source varchar(100) GENERATED ALWAYS AS (CASE WHEN deleted=b'0' AND status IN ('PENDING','APPROVED','CONSUMED') THEN CONCAT(source_type,':',source_id) ELSE NULL END) STORED,UNIQUE KEY uk_payroll_offset_source(tenant_id,active_source)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS hrm_payroll_offset_event(id bigint NOT NULL AUTO_INCREMENT PRIMARY KEY,offset_id bigint,actor_id bigint,action varchar(32),reason varchar(1000),snapshot LONGTEXT,creator varchar(64) DEFAULT '',create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,updater varchar(64) DEFAULT '',update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted bit NOT NULL DEFAULT FALSE,tenant_id bigint NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO hrm_salary_option_template(code,parent_code,name,remark,system_flag,type,tax_enabled,visible,calculate_enabled) SELECT 150901,150,'批准税款工资退还','批准税款结算进入指定工资，成功回盘后核销，禁止人工及公式覆盖',1,1,0,1,1 WHERE NOT EXISTS(SELECT 1 FROM hrm_salary_option_template WHERE code=150901);
INSERT INTO hrm_salary_option_template(code,parent_code,name,remark,system_flag,type,tax_enabled,visible,calculate_enabled) SELECT 160901,160,'批准税款工资补扣','批准税款结算进入指定工资，累计计税前计入该批次待结算基数',1,2,0,1,1 WHERE NOT EXISTS(SELECT 1 FROM hrm_salary_option_template WHERE code=160901);
